export const Schema = z.object({
    世界: z.object({
        当前日期: z.string(),
        当前时段: z.string(),
        当前地点: z.string(),
        天气: z.string(),
        当前学期: z.string(),
        当前周次: z.coerce.number().transform(v => Math.max(v, 1)),
        当前节日: z.string(),
        当前大型活动: z.string(),
        世界氛围: z.string(),
        新闻热词: z.array(z.string()).max(8).catch([]),
        活跃事件: z.record(z.string().describe('事件名'), z.string().describe('事件描述')),
    }),
    地图: z.object({
        主城区: z.array(z.string()).catch([]),
        校内区域: z.array(z.string()).catch([]),
        危险区: z.array(z.string()).catch([]),
        当前可达地点: z.array(z.string()).catch([]),
    }),
    主角: z.object({
        姓名: z.string(),
        性别: z.enum(['男', '女', '其他']),
        年龄: z.coerce.number().transform(v => _.clamp(v, 16, 40)),
        身份: z.string(),
        院系: z.string(),
        年级: z.string(),
        阵营: z.string(),
        阶位: z.enum(['F【一阶】', 'E【二阶】', 'D【三阶】', 'C【四阶】', 'B【五阶】', 'A【六阶】', 'S【七阶】', 'SS【八阶】', 'SSS【九阶】', 'SSS【十阶】']),
        异能名称: z.string(),
        异能类型: z.string(),
        异能描述: z.string(),
        异能负荷: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        体能: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        精神: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        卫生状态: z.object({
            清洁度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
            疲劳度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
            饱腹度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
            伤势: z.string(),
            今日作息: z.string(),
        }),
        性格: z.string().prefault('暂无'),
        外貌: z.string(),
        穿着: z.string(),
        身材: z.string().prefault('暂无'),
        当前行动: z.string(),
        当前姿势: z.string(),
        内心: z.string(),
        资产: z.object({
            学分点: z.coerce.number().transform(v => Math.max(v, 0)),
            现金: z.coerce.number().transform(v => Math.max(v, 0)),
            宿舍等级: z.string(),
        }),
        装备: z.record(z.string().describe('装备槽位'), z.object({
            名称: z.string(),
            阶位: z.string(),
            效果: z.string(),
        })),
        背包: z.record(z.string().describe('物品名'), z.object({
            描述: z.string(),
            数量: z.coerce.number().transform(v => Math.max(v, 0)).prefault(1),
        })),
        住所情况: z.string().prefault('暂无'),
        性癖: z.string().prefault('未展开记录'),
        阴道: z.string().prefault('未展开记录'),
        肛门: z.string().prefault('未展开记录'),
        最近性行为: z.string().prefault('无'),
    }),
    天赋面板: z.object({
        主天赋: z.object({
            名称: z.string(),
            阶位: z.string(),
            描述: z.string(),
            当前开发度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        }),
        副天赋: z.array(z.object({
            名称: z.string(),
            阶位: z.string(),
            描述: z.string(),
        })).catch([]),
        特训方向: z.array(z.string()).catch([]),
        已觉醒标签: z.array(z.string()).catch([]),
    }),
    焦点人物: z.record(z.string().describe('角色名'), z.object({
        性别: z.enum(['女', '男', '其他']),
        身份: z.string(),
        阵营: z.string(),
        阶位: z.string(),
        异能: z.string(),
        当前状态: z.string(),
        关系定位: z.string(),
        好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        信赖度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        关键印象: z.string(),
        外貌: z.string().prefault('暂无'),
        性格: z.string().prefault('暂无'),
        身材: z.string().prefault('暂无'),
        穿着: z.string().prefault('暂无'),
        当前行动: z.string().prefault('暂无'),
        当前姿势: z.string().prefault('暂无'),
        内心: z.string().prefault('暂无'),
        性癖: z.string().prefault('未展开记录'),
        阴道: z.string().prefault('未展开记录'),
        肛门: z.string().prefault('未展开记录'),
        最近性行为: z.string().prefault('无'),
    })),
    长期人物档案: z.record(z.string().describe('角色名'), z.object({
        性别: z.enum(['女', '男', '其他']),
        类别: z.string(),
        阵营: z.string(),
        简述: z.string(),
        近期动向: z.string(),
    })),
    阵营关系: z.record(z.string().describe('阵营名'), z.object({
        立场: z.string(),
        与主角关系: z.string(),
        热度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
    })),
    公共舆情: z.object({
        新闻: z.array(z.object({
            标题: z.string(),
            摘要: z.string(),
            热度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
            频道: z.string(),
            时间: z.string(),
        })).max(8).catch([]),
        评论: z.array(z.object({
            用户: z.string(),
            内容: z.string(),
            倾向: z.enum(['支持', '中立', '质疑', '玩梗']),
            点赞: z.coerce.number().transform(v => Math.max(v, 0)),
        })).max(10).catch([]),
        表白墙: z.array(z.object({
            发布者: z.string(),
            内容: z.string(),
            状态: z.string(),
        })).max(6).catch([]),
    }),
    编年史: z.object({
        最近事件: z.array(z.string()).max(8).catch([]),
        学期大事: z.array(z.string()).max(6).catch([]),
    }),
    秘匿角色: z.object({
        雾岛真绪: z.object({
            条目启用: z.boolean().catch(false),
            公开可见: z.boolean().catch(false),
            当前身份: z.string(),
            占据能力: z.object({
                已开启: z.boolean().catch(false),
                触发条件: z.string(),
                当前目标: z.string(),
                风险: z.string(),
                代价: z.string(),
                暴露度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
                已占据记录: z.array(z.string()).catch([]),
            }),
        }),
    }),
});
